import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as t,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const y=JSON.parse('{"title":"CodeBuddy 术语表","description":"不教操作，只解释 CodeBuddy 家族里容易撞名的词：三种编程形态、WorkBuddy、混元、国内站 / 国际站、CODEBUDDY.md。","frontmatter":{"title":"CodeBuddy 术语表","description":"不教操作，只解释 CodeBuddy 家族里容易撞名的词：三种编程形态、WorkBuddy、混元、国内站 / 国际站、CODEBUDDY.md。","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"zh/products/codebuddy/codebuddy-glossary.md","filePath":"zh/products/codebuddy/codebuddy-glossary.md","lastUpdated":1787107158000}'),r={name:"zh/products/codebuddy/codebuddy-glossary.md"};function n(s,d,c,l,p,i){return t(),o("div",null,[...d[0]||(d[0]=[a(`<h1 id="codebuddy-术语表" tabindex="-1">CodeBuddy 术语表 <a class="header-anchor" href="#codebuddy-术语表" aria-label="Permalink to &quot;CodeBuddy 术语表&quot;">​</a></h1><p>不教操作，只解释「是什么 / 不是什么」。选哪个入口看 <a href="./">学习地图</a>。</p><h2 id="概念关系" tabindex="-1">概念关系 <a class="header-anchor" href="#概念关系" aria-label="Permalink to &quot;概念关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>腾讯 AI（与本目录相关的部分）</span></span>
<span class="line"><span>├── CodeBuddy — 编码产品族</span></span>
<span class="line"><span>│   ├── IDE</span></span>
<span class="line"><span>│   ├── 插件（装进 VS Code / JetBrains 等）</span></span>
<span class="line"><span>│   └── CodeBuddy Code（CLI，命令 codebuddy）</span></span>
<span class="line"><span>│       ├── 交互 REPL</span></span>
<span class="line"><span>│       ├── print（-p）</span></span>
<span class="line"><span>│       └── CLI 自己的 plugin / Skills / MCP</span></span>
<span class="line"><span>├── WorkBuddy — 办公工作台（不是编码主线）</span></span>
<span class="line"><span>├── 元宝 — 通用助手</span></span>
<span class="line"><span>└── 混元 — 模型（CodeBuddy 可切换的引擎之一）</span></span></code></pre></div><h2 id="codebuddy" tabindex="-1">CodeBuddy <a class="header-anchor" href="#codebuddy" aria-label="Permalink to &quot;CodeBuddy&quot;">​</a></h2><p><strong>是什么</strong>：腾讯云的 AI 辅助编程产品。官方定义（<a href="https://www.codebuddy.cn/docs/" target="_blank" rel="noreferrer">文档总览</a>、<a href="https://cloud.tencent.com/document/product/1831/134343" target="_blank" rel="noreferrer">产品概述</a>）是同时支持 <strong>IDE、插件、CLI</strong> 三种形态。</p><p><strong>不是什么</strong>：不是混元本身，也不是元宝，更不是 WorkBuddy。官网营销句「基于混元代码大模型」说的是模型来源之一；同一套官方文档还写支持 DeepSeek 等。</p><p>三种形态共享同一账号资源配额（<a href="https://www.codebuddy.cn/docs/cli/troubleshooting" target="_blank" rel="noreferrer">故障排查</a>）。</p><h2 id="codebuddy-ide" tabindex="-1">CodeBuddy IDE <a class="header-anchor" href="#codebuddy-ide" aria-label="Permalink to &quot;CodeBuddy IDE&quot;">​</a></h2><p><strong>是什么</strong>：独立安装的编辑器。官方定位：产设研一体工作台，主打「对话即编程」。面向产品 / 设计师 / 全栈 / 编程初学者。</p><p><strong>为什么需要</strong>：插件留在你现有 IDE 里打辅助；IDE 把需求、设计、代码、部署放进同一个产品。</p><p><strong>不是什么</strong>：不是 VS Code 插件的皮肤。系统要求是 macOS 11+ / Windows 10+（<a href="https://www.codebuddy.cn/docs/ide/Getting-Started/Installation" target="_blank" rel="noreferrer">安装和登录</a>）。</p><h2 id="codebuddy-插件" tabindex="-1">CodeBuddy 插件 <a class="header-anchor" href="#codebuddy-插件" aria-label="Permalink to &quot;CodeBuddy 插件&quot;">​</a></h2><p><strong>是什么</strong>：装进已有编辑器的扩展。市场搜索名官方写 <strong>腾讯云代码助手</strong>。宿主包括 VS Code、Visual Studio、JetBrains 系列、Android Studio，以及微信开发者工具（<a href="https://www.codebuddy.cn/docs/plugin/" target="_blank" rel="noreferrer">插件页</a>）。</p><p><strong>为什么需要</strong>：你已经有编辑器和工作流，只想要补全、对话、工程问答。</p><p><strong>不是什么</strong>：</p><ul><li>不是 CLI 的 <code>codebuddy plugin</code></li><li>本站不因此写微信或 QQ 产品教程；微信开发者工具只是官方列出的宿主之一</li></ul><h2 id="codebuddy-code" tabindex="-1">CodeBuddy Code <a class="header-anchor" href="#codebuddy-code" aria-label="Permalink to &quot;CodeBuddy Code&quot;">​</a></h2><p><strong>是什么</strong>：面向专业工程师的 AI CLI。可执行文件 <code>codebuddy</code>，npm 包 <code>@tencent-ai/codebuddy-code</code>。官方适用：DevOps / 运维 / SRE / 资深开发者。</p><p><strong>三张脸</strong>（同一产品，不是三个产品）：</p><table tabindex="0"><thead><tr><th>面</th><th>入口</th></tr></thead><tbody><tr><td>交互 REPL</td><td><code>codebuddy</code></td></tr><tr><td>打印 / 无头</td><td><code>codebuddy -p &quot;...&quot;</code></td></tr><tr><td>进阶托管</td><td><code>codebuddy --serve</code>、<code>daemon</code>、<code>--bg</code></td></tr></tbody></table><p><strong>不是什么</strong>：不是已停更的某个「腾讯 Copilot」口头禅。国内登录域确实是 <code>copilot.tencent.com</code>，那是认证站，不是另一个产品名。</p><h2 id="workbuddy" tabindex="-1">WorkBuddy <a class="header-anchor" href="#workbuddy" aria-label="Permalink to &quot;WorkBuddy&quot;">​</a></h2><p><strong>是什么</strong>：官方原文（<a href="https://www.codebuddy.cn/docs/workbuddy/" target="_blank" rel="noreferrer">WorkBuddy 简介</a>）——「WorkBuddy 是腾讯出品的全场景 AI 办公工作台。」文档站把它和 CodeBuddy IDE / 插件 / CLI 并列成一级入口。</p><p><strong>为什么出现在这张表</strong>：家族完备要求一级入口不能从地图消失。#78 只收 CodeBuddy 编码三形态，所以 WorkBuddy 只占一行。</p><p><strong>不是什么</strong>：不是 CodeBuddy IDE 的移动版。小程序和 App 是 WorkBuddy 自己的入口。</p><h2 id="元宝" tabindex="-1">元宝 <a class="header-anchor" href="#元宝" aria-label="Permalink to &quot;元宝&quot;">​</a></h2><p><strong>是什么</strong>：腾讯的通用 AI 助手。<a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a>。</p><p><strong>不是什么</strong>：不是 CodeBuddy。本目录不写教程（#76）。</p><h2 id="混元" tabindex="-1">混元 <a class="header-anchor" href="#混元" aria-label="Permalink to &quot;混元&quot;">​</a></h2><p><strong>是什么</strong>：腾讯自研大模型。<a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a>、<a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">云产品 tclm</a>。CodeBuddy 官方写「支持混元、DeepSeek 等多种对话大模型」。</p><p><strong>不是什么</strong>：不是一个编码 IDE，也不是你要 <code>npm install</code> 的东西。本目录不写混元 API 教程（#77）。</p><h2 id="国内站-国际站" tabindex="-1">国内站 / 国际站 <a class="header-anchor" href="#国内站-国际站" aria-label="Permalink to &quot;国内站 / 国际站&quot;">​</a></h2><p><strong>是什么</strong>：两套站点与登录。</p><table tabindex="0"><thead><tr><th></th><th>国内</th><th>国际</th></tr></thead><tbody><tr><td>文档 / 官网</td><td>codebuddy.cn</td><td>codebuddy.ai</td></tr><tr><td>CLI 登录选项</td><td>Chinese Site → copilot.tencent.com</td><td>International Site → codebuddy.ai</td></tr><tr><td>IDE 下载（官方表）</td><td><a href="https://copilot.tencent.com/ide" target="_blank" rel="noreferrer">copilot.tencent.com/ide</a></td><td><a href="https://www.codebuddy.ai/" target="_blank" rel="noreferrer">codebuddy.ai</a></td></tr></tbody></table><p><strong>为什么要分</strong>：模型清单和认证域不同。官方快速开始写：国内站「支持国内主流模型」，国际站「支持海外主流模型」。</p><p><strong>不是什么</strong>：不是「一个站过时了」。两边都会更新；若英文总览少写了「插件」这一形态，以中文总览和腾讯云 1831 文档为准。</p><h2 id="企业版" tabindex="-1">企业版 <a class="header-anchor" href="#企业版" aria-label="Permalink to &quot;企业版&quot;">​</a></h2><p><strong>是什么</strong>：SaaS 企业版（旗舰版）和专有云专享版。登录走腾讯统一身份或企业管理员下发的地址。</p><p><strong>不是什么</strong>：不是个人版换皮。购买和专享版流程不在本教程展开。</p><h2 id="codebuddy-md" tabindex="-1"><code>CODEBUDDY.md</code> <a class="header-anchor" href="#codebuddy-md" aria-label="Permalink to &quot;\`CODEBUDDY.md\`&quot;">​</a></h2><p><strong>是什么</strong>：官方从 Claude Code 迁移时对应 <code>CLAUDE.md</code> 的「AI 指令和记忆文档」。用户级路径在迁移示例里是 <code>~/.codebuddy/CODEBUDDY.md</code>。</p><p><strong>为什么需要</strong>：把稳定约定从对话里抽出来，避免每次重讲。</p><p><strong>不是什么</strong>：不是 CLI plugin 清单，也不是 Skills 目录。Skills 在 <code>~/.codebuddy/skills/</code>；自定义斜杠命令在 <code>.codebuddy/commands/</code>。</p><p>仓库根是否自动读 <code>CODEBUDDY.md</code>，官方故障排查没有写成一句硬规则。以本机 <code>/config</code> 和官方「记忆」页为准。</p><h2 id="权限模式" tabindex="-1">权限模式 <a class="header-anchor" href="#权限模式" aria-label="Permalink to &quot;权限模式&quot;">​</a></h2><p><strong>是什么</strong>：CLI 决定「这次工具调用要不要问你」的档位。<code>--permission-mode</code> 官方值：<code>default</code>、<code>acceptEdits</code>、<code>auto</code>、<code>dontAsk</code>、<code>plan</code>、<code>bypassPermissions</code>。交互里 <code>Shift+Tab</code> 的文案是 <code>default → bypass → accept → plan</code>。</p><p><strong>为什么分两套名字</strong>：键位提示用短名，flag 用全名。写脚本用 flag 全名。</p><p><strong>不是什么</strong>：不是沙箱。沙箱（<code>--sandbox</code>，官方标 Beta）限制批准之后能碰到的文件系统 / 网络。权限过了，沙箱仍可能拦住。</p><h2 id="cli-plugin-vs-编辑器插件" tabindex="-1">CLI plugin vs 编辑器插件 <a class="header-anchor" href="#cli-plugin-vs-编辑器插件" aria-label="Permalink to &quot;CLI plugin vs 编辑器插件&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>编辑器插件</th><th>CLI plugin</th></tr></thead><tbody><tr><td>装在哪</td><td>VS Code / JetBrains…</td><td><code>codebuddy plugin install</code></td></tr><tr><td>官方文档树</td><td><code>/docs/plugin/</code></td><td><code>/docs/cli/</code> 的插件系统 / 插件市场</td></tr><tr><td>解决什么</td><td>在已有 IDE 里补全和对话</td><td>给终端 agent 打包 Skills / hooks / 工具</td></tr></tbody></table><p>两者都叫「插件」，不是同一次安装。</p><h2 id="已退役或易过时的说法" tabindex="-1">已退役或易过时的说法 <a class="header-anchor" href="#已退役或易过时的说法" aria-label="Permalink to &quot;已退役或易过时的说法&quot;">​</a></h2><p>本站<strong>不要</strong>再写成事实的句子：</p><ul><li>「CodeBuddy 只有插件」——官方一级是三种形态</li><li>「CodeBuddy 就是混元 IDE」——混元是模型</li><li>「<code>gh</code> 式腾讯 Copilot 扩展」——现行 CLI 是独立包 <code>@tencent-ai/codebuddy-code</code></li><li>把 WorkBuddy 写成 CodeBuddy 的一种 Mode</li></ul>`,55)])])}const m=e(r,[["render",n]]);export{y as __pageData,m as default};
